#!/usr/bin/env bash
# Builds glow for one GOOS/GOARCH and packages it into dist/ as
# glow_<version>_<Os>_<arch>.tar.gz (.zip on Windows). Each archive holds a
# single top-level directory with the binary, README, LICENSE, shell
# completions and the manpage.
#
# Usage: .github/scripts/dist.sh <goos> <goarch> [version]
#
# A leading "v" is stripped from the version. Without a version, the build is
# labelled snapshot-<short commit>.
set -euo pipefail

goos=$1
goarch=$2
commit=${GITHUB_SHA:-}
version=${3:-}
version=${version#v}
if [[ -z $version ]]; then
	version="snapshot-${commit:0:7}"
fi

case $goarch in
amd64) arch=x86_64 ;;
*) arch=$goarch ;;
esac
os="$(tr '[:lower:]' '[:upper:]' <<<"${goos:0:1}")${goos:1}"
ext=""
if [[ $goos == windows ]]; then
	ext=.exe
fi
name="glow_${version}_${os}_${arch}"

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
stage="$work/$name"
mkdir -p "$stage/completions" "$stage/manpages" dist

# Completions and the manpage are generated by a native build, since the target
# binary may not run on this machine.
go build -o "$work/glow-host" .
for shell in bash zsh fish; do
	"$work/glow-host" completion "$shell" >"$stage/completions/glow.$shell"
done
"$work/glow-host" man | gzip -9n >"$stage/manpages/glow.1.gz"

CGO_ENABLED=0 GOOS=$goos GOARCH=$goarch go build -trimpath \
	-ldflags "-s -w -X main.Version=$version -X main.CommitSHA=$commit" \
	-o "$stage/glow$ext" .
cp README.md LICENSE "$stage/"

if [[ $goos == windows ]]; then
	(cd "$work" && zip -qr - "$name") >"dist/$name.zip"
else
	tar -C "$work" -czf "dist/$name.tar.gz" "$name"
fi
echo "dist/$name"
